"""Writes the narration script and the storyboard / edit decision list from remotion/src/timeline.json,
so the documents always match the rendered film."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parents[1]
OUT = HERE.parent
tl = json.loads((HERE / "remotion/src/timeline.json").read_text(encoding="utf-8"))
fmt = lambda x: f"{int(x // 60)}:{x % 60:05.2f}"

SCENE_NAMES = {
    "S1": "Hook — the procurement problem (illustration)", "S2": "Why it matters — the public site", "S3": "Buyer set-up: sign-in, organisation, dashboard, wallet",
    "S4": "The request: scope, rules, suppliers, publish on NEAR", "S5": "Suppliers quote under seal", "S6": "Deadline, close and integrity check",
    "S7": "Evaluation: published rules, then private AI", "S8": "Award and testnet escrow funding", "S9": "Delivery, release and spending controls",
    "S10": "Records and close",
}
CAM = {"buyer": "Buyer camera (Northwind Studio)", "supplierA": "Supplier A camera (Clearline)", "supplierB": "Supplier B camera (Harbor Digital)"}

# ---------------------------------------------------------------- narration script
vo = ["# VeilProcure explainer — narration script", "",
      f"Final film: {tl['durationSec']} s. Voice: Kokoro `af_heart` (open-source neural text-to-speech, Apache-2.0, generated locally; a synthetic voice, not a human narrator). "
      f"{len(tl['voice'])} lines, {sum(len(v['text'].split()) for v in tl['voice'])} words, {sum(v['end'] - v['start'] for v in tl['voice']):.1f} s of speech. "
      "\"Veil Procure\" is written as two words only so the voice pronounces it; captions read \"VeilProcure\".", ""]
scene = None
for v in tl["voice"]:
    sid = v["line"].split("-")[0]
    if v["line"] == "S9-4":
        sid = "S10"
    if sid != scene:
        scene = sid
        vo += ["", f"## {sid} — {SCENE_NAMES[sid]}", ""]
    vo.append(f"**{fmt(v['start'])} – {fmt(v['end'])}** · {v['text'].replace('Veil Procure', 'VeilProcure').replace('A.I.', 'AI')}")
    vo.append("")
(OUT / "VeilProcure_Voiceover_Script.md").write_text("\n".join(vo), encoding="utf-8")

# ---------------------------------------------------------------- storyboard and EDL
e = ["# VeilProcure explainer — storyboard and edit decision list", "",
     f"Single film, 1920 × 1080, 30 fps, {tl['durationSec']} s. Built in Remotion 4.0.539 from `remotion/src/timeline.json` (generated by `scripts/build_timeline.py`); this table is generated from the same file.", "",
     "**Sources.** Three lossless screen captures of the real app (Chromium via Playwright, DevTools screencast, 1920 × 1080 PNG → constant 30 fps H.264 CRF 13, idle holds capped at 6 s; no frame edited): `public/footage/buyer.mp4`, `supplierA.mp4`, `supplierB.mp4`. "
     "Source times below are seconds into those files. *Rate* is the playback speed (typing is sped up; static confirmation states are slowed). *Zoom* is the focus rectangle in source pixels (x, y, width; height follows 16:9) — the window eases between rectangles.",
     "", "**Look.** Recorded screens sit in a rounded window on the app's canvas (soft mint glow) with a role label (Buyer / Supplier) top left, the chapter label top centre and, on every financial shot, the badge *NEAR TESTNET • test tokens, not real-money settlement* top right. Framing keeps every card and line whole at the window's left and right edges (app pages frame the content column, dialogs and public pages are centred); scrolled pages fade softly at the window's top and bottom edges. Highlights are mint outlines with a night-green tag placed beside, above, below or inside the box so it never covers the text it points at. Captions sit below the window, never over UI values. Dark scenes (hook, diagram, RPC cards, outro) use the app's night green `#0d201c` and mint `#00ec97`; type is Manrope (the app's font) and JetBrains Mono for hashes.",
     "", "**Music and sound.** Original bed generated for this film (`audio/music_bed.wav`, numpy synthesis: additive pads, soft 92 bpm pulse from 30 s, sparse plucked arpeggio from 45 s, lift at the escrow scene); ducked −11 dB under narration; synthesised soft chime on each on-chain confirmation and RPC success card, light whoosh into the product, the diagram and the outro. Final mix −16 LUFS integrated, −1.5 dBTP.", ""]
scene = None
for s in tl["segments"]:
    sid = s["id"].split("-")[0]
    if sid != scene:
        scene = sid
        e += ["", f"## {sid} — {SCENE_NAMES[sid]}", "", "| In | Out | Shot | Source | Rate | Zoom | Highlights / content |", "|---|---|---|---|---|---|---|"]
    a, b = s["start"], s["start"] + s["dur"]
    if s["type"] == "footage":
        mv = s.get("moves") or []
        zoom = " → ".join(f"({m['x']},{m['y']},{m['w']})" for m in mv)
        hl = "; ".join(f"“{c['text']}” {c['t0']:.1f}–{c['t1']:.1f} s" for c in s.get("callouts", []) if c.get("text")) or "—"
        src = f"{CAM[s['cam']]} {s['src']:.1f}–{s['src'] + s['dur'] * s.get('rate', 1):.1f} s"
        e.append(f"| {fmt(a)} | {fmt(b)} | {s['id']} screen recording | {src} | ×{s.get('rate', 1)} | {zoom} | {hl} |")
    elif s["type"] == "rpc":
        hashes = ", ".join(f"`{t['method']}` {t['status']} `{t['txHash'][:10]}…`" for t in s["txs"])
        e.append(f"| {fmt(a)} | {fmt(b)} | {s['id']} RPC card “{s['title']}” | NEAR testnet RPC `EXPERIMENTAL_tx_status` (rpc-verification.json) | — | — | {hashes}{'; balance ' + s['balance']['before'] + ' → ' + s['balance']['after'] + ' NEAR' if s.get('balance') else ''} |")
    elif s["type"] == "hook":
        e.append(f"| {fmt(a)} | {fmt(b)} | {s['id']} motion graphic | Illustration, labelled “Illustration · not a product screen” | — | — | Headline “Business purchasing shouldn't mean scattered bids, opaque decisions, and payment uncertainty.”; scattered quote e-mails, a spreadsheet of mismatched cells, an “APPROVED?” stamp, “Payment: send it when it's done”; at 3.6 s the VeilProcure logo and one-line description; clutter collapses into the product |")
    elif s["type"] == "diagram":
        e.append(f"| {fmt(a)} | {fmt(b)} | {s['id']} motion graphic | Illustration, labelled | — | — | “How a sealed bid is checked”: quote fields + salt → hash → fingerprint on NEAR testnet; after the deadline the opened quote + same salt is hashed again → match → commitment verified. “Proves: unchanged since sealed. Does not prove secrecy: quotes are encrypted at rest and the platform holds that key.” |")
    elif s["type"] == "outro":
        e.append(f"| {fmt(a)} | {fmt(b)} | {s['id']} closing card | VP monogram (video-only light version) | — | — | “Private bids. Intelligent decisions. Payments under your control.” · veilprocure.netlify.app · github.com/Olalekan2345/veilprocure · “Public beta on NEAR testnet · test tokens have no monetary value · escrow contract not audited” |")
e += ["", "## Narration cues", "", "| In | Out | Line |", "|---|---|---|"]
e += [f"| {fmt(v['start'])} | {fmt(v['end'])} | {v['text'].replace('Veil Procure', 'VeilProcure').replace('A.I.', 'AI')} |" for v in tl["voice"]]
e += ["", "## Transitions", "", "Cross-dissolves only: 0.5 s into the product and the outro, 0.35–0.4 s between scenes, 0.2 s between shots of one scene. No wipes, no fake UI animation; camera moves ease with cubic-bezier(0.65, 0, 0.35, 1)."]
(OUT / "VeilProcure_Storyboard_and_EDL.md").write_text("\n".join(e) + "\n", encoding="utf-8")
print("written voiceover script and EDL")
